<?php
session_start(); require_once 'config/conexao.php'; require_once 'config/auth.php'; exigir_cargo(['administrador','gerente']);
$inicio=$_GET['inicio']??date('Y-m-01');$fim=$_GET['fim']??date('Y-m-d');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$inicio)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$fim)||$inicio>$fim){$inicio=date('Y-m-01');$fim=date('Y-m-d');}
$q=$pdo->prepare("SELECT COUNT(*) total, SUM(status IN ('pronto','entregue')) concluidos, SUM(status='cancelado') cancelados FROM pedidos WHERE data_pedido BETWEEN ? AND ?");$q->execute([$inicio,$fim]);$ped=$q->fetch();
$q=$pdo->prepare("SELECT COALESCE(tipo,'direta') tipo,COUNT(*) quantidade,SUM(total) valor FROM vendas WHERE COALESCE(data_venda,DATE(criado_em)) BETWEEN ? AND ? AND status<>'cancelada' GROUP BY COALESCE(tipo,'direta')");$q->execute([$inicio,$fim]);$vendas=$q->fetchAll();$totalVendas=0;$qtdVendas=0;foreach($vendas as $v){$totalVendas+=(float)$v['valor'];$qtdVendas+=(int)$v['quantidade'];}
$baixo=$pdo->query('SELECT id,nome,codigo,categoria,quantidade,estoque_minimo,unidade FROM produtos WHERE ativo=1 AND quantidade<=estoque_minimo ORDER BY quantidade ASC,nome')->fetchAll();
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relatórios gerenciais</title><link rel="stylesheet" href="style.css"></head><body><main class="app"><header class="topbar"><h2>Relatórios gerenciais</h2><a class="link-sair" href="painel.php">← Painel</a></header><section class="content"><?php mostrar_flash();?><h1>Indicadores da gráfica</h1><form class="form-box" method="get"><div class="form-row"><div><label>Data inicial</label><input type="date" name="inicio" value="<?=h($inicio)?>" required></div><div><label>Data final</label><input type="date" name="fim" value="<?=h($fim)?>" required></div><div style="align-self:end"><button>Aplicar período</button></div></div><a class="button-link" href="relatorio_pdf.php?inicio=<?=urlencode($inicio)?>&fim=<?=urlencode($fim)?>">Gerar relatório PDF</a></form>
<div class="cards"><article class="module-card"><h2><?=number_format((int)$ped['total'],0,',','.')?></h2><p>Pedidos recebidos no período</p></article><article class="module-card"><h2><?=number_format((int)$ped['concluidos'],0,',','.')?></h2><p>Pedidos concluídos (prontos ou entregues)</p></article><article class="module-card"><h2><?=number_format($qtdVendas,0,',','.')?></h2><p>Vendas/faturamentos no período</p></article><article class="module-card"><h2>R$ <?=number_format($totalVendas,2,',','.')?></h2><p>Faturamento não cancelado</p></article><article class="module-card"><h2><?=count($baixo)?></h2><p>Produtos com estoque baixo</p></article></div>
<h2>Vendas por tipo</h2><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Quantidade</th><th>Valor total</th></tr></thead><tbody><?php foreach($vendas as $v):?><tr><td><?=$v['tipo']==='servico'?'Serviços gráficos':'Vendas diretas'?></td><td><?=h($v['quantidade'])?></td><td>R$ <?=number_format((float)$v['valor'],2,',','.')?></td></tr><?php endforeach;?><?php if(!$vendas):?><tr><td colspan="3">Sem vendas no período.</td></tr><?php endif;?></tbody></table></div>
<h2>Produtos com estoque baixo</h2><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Código</th><th>Categoria</th><th>Disponível</th><th>Mínimo</th></tr></thead><tbody><?php foreach($baixo as $p):?><tr><td><?=h($p['nome'])?></td><td><?=h($p['codigo']?:'—')?></td><td><?=h($p['categoria']?:'—')?></td><td><?=h($p['quantidade'])?> <?=h($p['unidade'])?></td><td><?=h($p['estoque_minimo'])?> <?=h($p['unidade'])?></td></tr><?php endforeach;?><?php if(!$baixo):?><tr><td colspan="5">Nenhum produto abaixo do estoque mínimo.</td></tr><?php endif;?></tbody></table></div>
<p class="subtitle">Período analisado: <?=date('d/m/Y',strtotime($inicio))?> a <?=date('d/m/Y',strtotime($fim))?>. O alerta de estoque considera quantidade disponível menor ou igual ao estoque mínimo.</p></section></main></body></html>
